import {escapeHtml as e,money,sum,localDate,displayDate,monthName,inMonth,parseMoney,moneyInput,transactionCsv,filteredTransactions,icon} from './lib.js';
const root=document.querySelector('#app'),modal=document.querySelector('#modal');
const routes={dashboard:['Visão geral','grid'],transactions:['Lançamentos','arrows'],accounts:['Contas e carteiras','wallet'],categories:['Categorias','tag'],budgets:['Orçamentos','pie'],goals:['Metas financeiras','target'],recurring:['Recorrências','repeat'],reports:['Relatórios','chart'],import:['Importar extrato','upload'],settings:['Configurações','settings']};
let session=null,data=null,workspaceId=null,route='dashboard',month=localDate().slice(0,7),loadId=0,authTab='login',page=1,installPrompt=null,importPreview=null,returnFocus=null;
let filters={search:'',type:'',status:'',account:'',category:''};
const store={get(key){try{return localStorage.getItem('fincontrol.'+key);}catch{return null;}},set(key,val){try{localStorage.setItem('fincontrol.'+key,val);}catch{}}};
const savedMonth=store.get('month');if(/^\d{4}-\d{2}$/.test(savedMonth||''))month=savedMonth;
const canEdit=()=>data?.role!=='Leitor';const isAdmin=()=>data?.role==='Administrador';
const button=(label,action,ico='',cls='',extra='')=>`<button type="button" class="btn ${cls}" data-action="${action}" ${extra}>${ico?icon(ico):''}${label}</button>`;
const ib=(label,action,ico,extra='')=>`<button type="button" class="icon-btn" title="${e(label)}" aria-label="${e(label)}" data-action="${action}" ${extra}>${icon(ico,16)}</button>`;
const badge=(i,color='')=>`<span class="badge-icon ${color}">${icon(i,18)}</span>`;
const field=(name,label,type='text',value='',extra='')=>`<label class="field">${label}<input name="${name}" type="${type}" value="${e(value)}" ${extra}></label>`;
const select=(name,label,options,value='',extra='')=>`<label class="field">${label}<select name="${name}" ${extra}>${options.map(([v,t])=>`<option value="${e(v)}" ${String(v)===String(value)?'selected':''}>${e(t)}</option>`).join('')}</select></label>`;
const empty=(title,description,action='',label='',ico='file',compact=false)=>`<div class="empty ${compact?'compact':''}">${badge(ico)}<h3>${e(title)}</h3><p>${e(description)}</p>${action&&canEdit()?button(label,action,'plus','small'):''}</div>`;
const safeError=err=>err?.message||'Não foi possível concluir. Tente novamente.';
function toast(message,error=false){const x=document.createElement('div');x.className='toast'+(error?' error':'');x.setAttribute('role',error?'alert':'status');x.innerHTML=icon(error?'info':'check')+`<span>${e(message)}</span>`;document.querySelector('#toasts').append(x);setTimeout(()=>x.remove(),6500);}
async function api(path,method='GET',body){
 let response;try{response=await fetch('/api'+path,{method,credentials:'same-origin',headers:{'X-FinControl':'1',...(body!==undefined?{'Content-Type':'application/json'}:{})},body:body===undefined?undefined:JSON.stringify(body)});}catch{throw new Error('Sem conexão com o FinControl. Confira se o computador que iniciou o sistema está ligado.');}
 const text=await response.text();let result;try{result=text?JSON.parse(text):null;}catch{result=null;}
 if(!response.ok){if(response.status===401&&session?.user&&!path.startsWith('/auth/')){session=null;data=null;root.innerHTML='';renderAuth();}throw new Error(result?.message||(response.status===429?'Muitas tentativas. Aguarde um minuto e tente novamente.':response.status===401?'Entre novamente para continuar.':'Não foi possível concluir a operação.'));}return result;
}
const w=(path,method='GET',body)=>api(`/w/${workspaceId}${path}`,method,body);
function setTheme(value){store.set('theme',value);document.documentElement.dataset.theme=value==='system'?(matchMedia('(prefers-color-scheme:dark)').matches?'dark':'light'):value;document.querySelectorAll('[data-theme-choice]').forEach(b=>b.classList.toggle('selected',b.dataset.themeChoice===value));}
matchMedia('(prefers-color-scheme:dark)').addEventListener('change',()=>{if((store.get('theme')||'system')==='system')setTheme('system');});
function renderAuth(){
 root.innerHTML=`<main class="auth-layout" id="content"><section class="auth-art"><div class="brand"><span class="logo-mark">f</span>FinControl</div><div><div class="eyebrow" style="color:#7bd5b8">CLAREZA PARA CADA ESCOLHA</div><h1>Seu financeiro.<br>No seu <em>ritmo.</em></h1><p>Mais organização para a sua vida. Mais controle para o seu negócio. Um espaço para cada objetivo.</p><div class="auth-features"><div>${icon('wallet')}Contas, receitas e despesas em um só lugar</div><div>${icon('users')}Espaços pessoais e equipes com permissões</div><div>${icon('shield')}Seus dados sob seu controle</div></div></div><footer>FINCONTROL &nbsp; / &nbsp; PESSOAL · MEI · EMPRESAS</footer></section><section class="auth-main">${ib('Alternar tema','theme','sun','class="auth-theme"')}<div class="auth-card"><span class="eyebrow">BEM-VINDO AO SEU PRÓXIMO PASSO</span><h2>${authTab==='login'?'Tudo em ordem começa aqui.':'Crie seu espaço financeiro.'}</h2><p>${authTab==='login'?'Entre para acompanhar o que realmente importa.':'Organize suas finanças com uma conta só sua.'}</p><div class="tabs" role="group" aria-label="Acesso"><button data-action="auth-login" class="${authTab==='login'?'active':''}">Entrar</button><button data-action="auth-register" class="${authTab==='register'?'active':''}">Criar conta</button></div><form id="auth-form"><div class="form-error" role="alert"></div>${authTab==='register'?field('nome','Seu nome','text','','required maxlength="120" autocomplete="name"'):''}${field('email','E-mail','email','','required maxlength="180" autocomplete="username"')}${field('senha','Senha','password','','required '+(authTab==='register'?'minlength="10" autocomplete="new-password"':'autocomplete="current-password"')+' maxlength="128"')}${authTab==='register'?`<small>Use uma senha ou frase com pelo menos 10 caracteres.</small><div class="form-grid">${select('perfil','Como vai usar?',[['Pessoal','Finanças pessoais'],['MEI','Microempresa / MEI'],['Empresa','Empresa']],'Pessoal')}${field('espaco','Nome do espaço','text','Meu financeiro','required maxlength="120"')}</div>${session?.requiresSetup?field('codigoInicial','Código inicial do computador','text','','required autocomplete="off"')+'<small>Há dados da versão anterior. Use o código mostrado na janela que iniciou o sistema.</small>':''}`:''}<button class="btn primary" type="submit">${authTab==='login'?'Entrar no meu espaço':'Criar minha conta'}${icon('right',16)}</button></form><p class="auth-note">${icon('lock',13)} Seus dados ficam no computador ou servidor que está executando o FinControl. O cadastro não conecta contas bancárias.</p></div></section></main>`;
 const themeBtn=root.querySelector('.auth-main>.icon-btn');themeBtn?.classList.add('auth-theme');
}
async function initialize(){
 try{session=await api('/session');if(!session.user){renderAuth();return;}workspaceId=session.workspaces.some(s=>String(s.id)===store.get('workspace'))?Number(store.get('workspace')):session.workspaces[0]?.id;
 if(!workspaceId)throw new Error('Sua conta está sem espaço financeiro. Entre novamente.');route=routes[location.hash.slice(1)]?location.hash.slice(1):'dashboard';renderShell();await reload();}
 catch(err){root.innerHTML=`<div class="startup" id="content">${badge('info')}<h1>Não foi possível conectar</h1><p>${e(safeError(err))}</p>${button('Tentar novamente','retry','refresh')}</div>`;}
}
function renderShell(){
 const nav=Object.entries(routes).map(([key,[title,ico]],idx)=>`${idx===0?'<div class="nav-group">SEU FINANCEIRO</div>':idx===4?'<div class="nav-group">PLANEJAMENTO</div>':idx===8?'<div class="nav-group">FERRAMENTAS</div>':''}<a href="#${key}" data-nav="${key}" class="${route===key?'active':''}" ${route===key?'aria-current="page"':''}>${icon(ico,17)}${title}</a>`).join('');
 root.innerHTML=`<div class="shell"><div class="mobile-backdrop" data-action="close-menu"></div><aside class="sidebar" id="sidebar" aria-label="Navegação principal"><div class="brand"><span class="logo-mark">f</span><div>FinControl<small>SEU FINANCEIRO</small></div></div><div class="workspace-picker"><label for="workspace">ESPAÇO FINANCEIRO</label><select id="workspace">${session.workspaces.map(s=>`<option value="${s.id}" ${s.id===workspaceId?'selected':''}>${e(s.nome)}</option>`).join('')}</select></div><nav class="nav">${nav}</nav><div class="sidebar-footer"><div class="user-summary"><span class="avatar">${e(session.user.nome.split(' ').map(x=>x[0]).slice(0,2).join('').toUpperCase())}</span><div><strong>${e(session.user.nome)}</strong><small>Minha conta</small></div><button class="logout" data-action="logout" aria-label="Sair da conta" title="Sair">${icon('logout',17)}</button></div></div></aside><div class="main"><header class="topbar">${ib('Abrir menu','menu','menu','aria-controls="sidebar" aria-expanded="false"')}<div class="breadcrumb"><span class="parent">Meu espaço</span><span class="divider">/</span><strong id="breadcrumb-title">${routes[route][0]}</strong></div><div class="top-actions"><span class="connection"><i class="tag-dot"></i><span id="connection-text">Conectado</span></span>${ib('Alternar claro e escuro','theme','sun')}<button class="btn primary" data-action="new-transaction">${icon('plus',16)}<span class="desktop-label">Novo lançamento</span></button></div></header><div id="offline-banner" class="offline-banner" hidden>Você está sem conexão. As alterações dependem do computador que executa o FinControl.</div><main class="content" id="content" tabindex="-1"></main></div></div>`;
 root.querySelector('[data-action="menu"]').classList.add('mobile-menu');root.querySelector('.topbar [data-action="theme"]').classList.add('theme-top');updateOnline();closeMenu();
}
async function reload(){
 const id=++loadId,space=workspaceId;const content=document.querySelector('#content');if(!data&&content)content.innerHTML='<div class="loading-state" role="status"><span class="spinner"></span>Carregando seu financeiro…</div>';
 try{const result=await w('/state?month='+encodeURIComponent(month));if(id!==loadId||space!==workspaceId)return;data=result;renderPage();const stamp=document.querySelector('#connection-text');if(stamp)stamp.textContent='Atualizado às '+new Date().toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'});}
 catch(err){if(id!==loadId)return;if(!data&&session?.user&&content)content.innerHTML=empty('Não foi possível carregar',safeError(err),'reload','Tentar novamente','info');else toast(safeError(err),true);}
}
function navigate(key){if(!routes[key])key='dashboard';route=key;page=1;closeMenu();document.querySelectorAll('[data-nav]').forEach(a=>{a.classList.toggle('active',a.dataset.nav===key);if(a.dataset.nav===key)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});if(data)renderPage();document.querySelector('#content')?.focus({preventScroll:true});window.scrollTo({top:0,behavior:'instant'});}
window.addEventListener('hashchange',()=>navigate(location.hash.slice(1)));
function monthControl(){return `<div class="month-switch">${ib('Mês anterior','prev-month','left')}<label class="month-field"><span aria-hidden="true">${e(monthName(month))}</span><input type="month" id="month" aria-label="Mês de referência" value="${month}" min="1901-01" max="9997-12"></label>${ib('Próximo mês','next-month','right')}</div>`;}
function renderPage(){
 if(!data)return;document.title=routes[route][0]+' · FinControl';document.querySelector('#breadcrumb-title').textContent=routes[route][0];document.querySelector('.topbar [data-action="new-transaction"]').hidden=!canEdit();
 const headings={dashboard:['Seu financeiro, com clareza.','Acompanhe os movimentos e planeje seus próximos passos.'],transactions:['Cada movimento, no lugar certo.','Receitas e despesas do período, sem perder nenhum detalhe.'],accounts:['Contas e carteiras','Uma visão completa dos seus saldos, em todos os lugares.'],categories:['Organize do seu jeito.','Categorias claras tornam suas decisões mais simples.'],budgets:['Planeje antes de gastar.','Defina limites mensais e acompanhe o que já foi utilizado.'],goals:['Dê um destino aos seus planos.','Acompanhe a reserva de cada objetivo financeiro.'],recurring:['Menos repetição. Mais controle.','Lançamentos automáticos, sempre pendentes até sua confirmação.'],reports:['Os números contam a história.','Resultados realizados e compromissos do período.'],import:['Do extrato para o controle.','Importe CSV ou OFX, confira a prévia e confirme quando estiver pronto.'],settings:['Um espaço com a sua cara.','Preferências, segurança, equipe e cuidado com seus dados.']};
 const creates={accounts:['Nova conta','new-account'],categories:['Nova categoria','new-category'],budgets:['Novo orçamento','new-budget'],goals:['Nova meta','new-goal'],recurring:['Nova recorrência','new-recurring']};
 const usesMonth=['dashboard','transactions','budgets','reports'].includes(route);
 let action=creates[route]&&canEdit()?button(creates[route][0],creates[route][1],'plus','primary'):route==='transactions'?button('Exportar CSV','export','download'):route==='reports'?button('Imprimir relatório','print','print'):'';
 const [title,subtitle]=headings[route];
 document.querySelector('#content').innerHTML=`<div class="page-heading"><div><div class="eyebrow" style="margin-bottom:8px">${e(data.workspace.perfil==='Pessoal'?'FINANÇAS PESSOAIS':data.workspace.perfil==='MEI'?'MICROEMPRESA / MEI':'GESTÃO FINANCEIRA')} &nbsp; / &nbsp; ${e(data.workspace.nome)}</div><h1>${title}</h1><p>${subtitle}</p></div><div class="page-actions">${usesMonth?monthControl():''}${action}</div></div>${!canEdit()?'<div class="notice">Você tem acesso de leitura a este espaço.</div>':''}<div id="page-body">${({dashboard:dashboard,transactions:transactionsPage,accounts:accountsPage,categories:categoriesPage,budgets:budgetsPage,goals:goalsPage,recurring:recurringPage,reports:reportsPage,import:importPage,settings:settingsPage}[route])()}</div><footer class="content-footer"><span>FinControl · ${e(data.workspace.nome)}</span><span>Seus dados. Seus planos. Seu controle.</span></footer>`;
 if(route==='settings'&&isAdmin())loadMembers();
}
function metric(label,value,ico,color,foot,balance=false){return `<article class="card metric ${balance?'balance':''}"><div class="metric-top"><span class="metric-label">${label}</span>${badge(ico,color)}</div><div class="metric-value num">${money(value)}</div><small>${icon(balance?'wallet':'arrows',11)}${foot}</small></article>`;}
function dashboard(){const d=data.dashboard,monthly=data.transactions.filter(t=>inMonth(t,month)),paid=monthly.filter(t=>t.pago),pending=monthly.filter(t=>!t.pago);return `${!data.transactions.length?`<div class="onboarding"><div class="inline">${badge('spark')}<div><h3>Seu próximo passo começa com um lançamento.</h3><p>Cadastre uma receita ou despesa para dar vida ao seu painel.</p></div></div>${canEdit()?button('Começar agora','new-transaction','plus','primary small'):''}</div>`:''}<section class="metrics" aria-label="Resumo financeiro">${metric('Saldo consolidado',d.saldoGeral,'wallet','','Todas as contas · todo o histórico',true)}${metric('Receitas do mês',d.totalReceitasMes,'up','','Valores recebidos no período')}${metric('Despesas do mês',d.totalDespesasMes,'down','red','Valores pagos no período')}${metric('Resultado do mês',d.economiaMes,'chart','blue','Receitas menos despesas pagas')}</section><div class="dashboard-grid"><section class="card"><div class="card-head"><div><h2>Seu fluxo financeiro</h2><p>Receitas e despesas realizadas nos últimos 6 meses</p></div><div class="legend"><span><i></i>Receitas</span><span><i class="expense"></i>Despesas</span></div></div>${barChart(d.receitasPorMes,d.despesasPorMes)}</section><section class="card"><div class="card-head"><div><h2>Para onde vai seu dinheiro</h2><p>Despesas pagas por categoria</p></div>${icon('pie',18)}</div>${donut(paid.filter(t=>t.tipo===2))}</section><section class="card"><div class="card-head"><div><h2>Últimos lançamentos</h2><p>Movimentações de ${e(monthName(month))}</p></div><a href="#transactions" class="text-btn">Ver todos ${icon('right',14)}</a></div>${monthly.length?`<div class="table-wrap mobile-cards">${transactionTable(monthly.slice(0,5),true)}</div>`:empty('Seu histórico começa aqui','Os lançamentos deste mês aparecerão nesta lista.','new-transaction','Adicionar lançamento','arrows',true)}<div class="card-footer">${pending.length} lançamento(s) pendente(s) neste mês</div></section><section class="card"><div class="card-head"><div><h2>De olho no orçamento</h2><p>O planejamento encontra a realidade</p></div><a href="#budgets" class="text-btn" aria-label="Ver orçamentos">${icon('right',16)}</a></div><div class="card-body">${budgetRows(true)}${d.orcamentoTotal?`<div class="budget-summary"><strong class="num">${money(d.orcamentoDisponivel)}</strong><p>${d.orcamentoDisponivel<0?'Acima do total planejado':'Disponível nas categorias com orçamento'}</p></div>`:''}</div></section></div>`;}
function barChart(income,expense){const max=Math.max(100,...income.map(x=>x.valor),...expense.map(x=>x.valor))*1.12;const width=620,height=225,top=18,bottom=190,left=48,plot=width-left-16;let marks='';for(let j=0;j<4;j++){let value=max*j/3,y=bottom-(bottom-top)*j/3;marks+=`<line x1="${left}" y1="${y}" x2="${width-8}" y2="${y}" class="chart-grid"/><text x="${left-9}" y="${y+4}" text-anchor="end" class="chart-label">${value>=1000?(value/1000).toFixed(1).replace('.',',')+' mil':Math.round(value)}</text>`;}income.forEach((v,i)=>{const center=left+(i+.5)*plot/6;const h1=v.valor/max*(bottom-top),h2=expense[i].valor/max*(bottom-top);marks+=`<rect x="${center-16}" y="${bottom-h1}" width="12" height="${Math.max(0,h1)}" rx="3" fill="var(--primary)"><title>Receitas de ${e(monthName(v.mes.slice(0,7)))}: ${money(v.valor)}</title></rect><rect x="${center+3}" y="${bottom-h2}" width="12" height="${Math.max(0,h2)}" rx="3" fill="var(--blue)"><title>Despesas: ${money(expense[i].valor)}</title></rect><text x="${center}" y="215" text-anchor="middle" class="chart-label">${new Date(v.mes).toLocaleDateString('pt-BR',{month:'short'}).replace('.','')}</text>`;});return `<div class="chart-wrap"><svg class="bar-chart" viewBox="0 0 ${width} ${height}" role="img" aria-label="Gráfico de receitas e despesas realizadas. Valores disponíveis na tabela abaixo.">${marks}</svg></div><details class="details-table"><summary>Ver valores do gráfico</summary><table class="data-table"><thead><tr><th>Mês</th><th>Receitas</th><th>Despesas</th></tr></thead><tbody>${income.map((x,i)=>`<tr><td>${e(monthName(x.mes.slice(0,7)))}</td><td>${money(x.valor)}</td><td>${money(expense[i].valor)}</td></tr>`).join('')}</tbody></table></details>`;}
const palette=['#118c79','#6598e2','#ddac64','#a194d4','#dd849a','#8ca7b6'];
function donut(rows){if(!rows.length)return empty('Ainda sem despesas pagas','Ao confirmar uma despesa, sua distribuição aparecerá aqui.','','','pie',true);const totals=new Map();rows.forEach(t=>totals.set(t.categoriaNome,(totals.get(t.categoriaNome)||0)+Math.round(t.valor*100)));let groups=[...totals.entries()].sort((a,b)=>b[1]-a[1]);if(groups.length>5)groups=[...groups.slice(0,5),['Outras',groups.slice(5).reduce((s,x)=>s+x[1],0)]];const total=groups.reduce((s,x)=>s+x[1],0);let cursor=0;const gradient=groups.map((x,i)=>{const start=cursor;cursor+=x[1]/total*100;return `${palette[i]} ${start}% ${cursor}%`;}).join(',');return `<div class="donut-layout"><div class="donut" style="background:conic-gradient(${gradient})" role="img" aria-label="Distribuição por categoria, detalhada ao lado"><div class="donut-center"><span>Total de despesas</span><strong class="num">${money(total/100)}</strong></div></div><ul class="category-legend" style="padding:0;margin:0">${groups.map((x,i)=>`<li><i style="background:${palette[i]}"></i><span class="cat-name" title="${e(x[0])}">${e(x[0])}</span><strong>${Math.round(x[1]/total*100)}%</strong></li>`).join('')}</ul></div>`;}
function transactionTable(rows,compact=false){return `<table class="data-table"><thead><tr><th>Descrição</th><th>Categoria</th>${compact?'':'<th>Conta</th>'}<th>Data</th><th>Situação</th><th class="money">Valor</th>${compact?'':'<th><span class="muted">Ações</span></th>'}</tr></thead><tbody>${rows.map(t=>`<tr><td class="description">${e(t.descricao)}${t.recorrente?'<small>Recorrente</small>':''}</td><td class="category">${e(t.categoriaNome)}</td>${compact?'':`<td class="account">${e(t.contaNome)}</td>`}<td class="date">${displayDate(t.data)}</td><td class="status"><span class="pill ${t.pago?'green':t.data.slice(0,10)<localDate()?'red':'orange'}"><i class="tag-dot"></i>${t.pago?'Confirmado':t.data.slice(0,10)<localDate()?'Em atraso':'Pendente'}</span></td><td class="money num ${t.tipo===1?'positive':'negative'}">${t.tipo===1?'+':'−'} ${money(t.valor)}</td>${compact?'':`<td class="actions"><div class="row-actions">${canEdit()?`${ib(t.pago?'Marcar como pendente':'Confirmar pagamento / recebimento','toggle-paid',t.pago?'repeat':'check',`data-id="${t.id}"`)}${ib('Editar lançamento','edit-transaction','edit',`data-id="${t.id}"`)}${ib('Excluir lançamento','delete-transaction','trash',`data-id="${t.id}"`)}`:'—'}</div></td>`}</tr>`).join('')}</tbody></table>`;}
function currentRows(){return filteredTransactions(data.transactions,{...filters,month});}
function transactionResults(){const all=currentRows(),limit=12,totalPages=Math.max(1,Math.ceil(all.length/limit));page=Math.max(1,Math.min(page,totalPages));return `${all.length?`<div class="table-wrap mobile-cards">${transactionTable(all.slice((page-1)*limit,page*limit))}</div>`:empty('Nenhum lançamento encontrado','Tente mudar o mês ou limpar os filtros.','new-transaction','Novo lançamento','search')}<div class="pagination"><span>${all.length} lançamento(s) · ${money(sum(all,t=>t.tipo===1?t.valor:-t.valor))}</span><div class="inline">${ib('Página anterior','prev-page','left',page===1?'disabled':'')}<span>${page} / ${totalPages}</span>${ib('Próxima página','next-page','right',page===totalPages?'disabled':'')}</div></div>`;}
function filterSelect(name,label,opts){return `<select class="input" data-filter="${name}" aria-label="${label}">${opts.map(([v,t])=>`<option value="${e(v)}" ${String(filters[name])===String(v)?'selected':''}>${e(t)}</option>`).join('')}</select>`;}
function transactionsPage(){return `<section class="card"><div class="filters"><div class="search">${icon('search',17)}<input data-filter="search" aria-label="Pesquisar lançamentos" placeholder="Buscar descrição, categoria ou conta…" value="${e(filters.search)}"></div>${filterSelect('type','Tipo de lançamento',[['','Todos os tipos'],[1,'Receitas'],[2,'Despesas']])}${filterSelect('status','Situação',[['','Todas as situações'],['paid','Confirmados'],['pending','Pendentes'],['late','Em atraso']])}${filterSelect('account','Filtrar conta',[['','Todas as contas'],...data.accounts.map(x=>[x.id,x.nome])])}${filterSelect('category','Filtrar categoria',[['','Todas as categorias'],...data.categories.map(x=>[x.id,x.nome])])}${ib('Limpar filtros','clear-filters','refresh')}</div><div id="transaction-results">${transactionResults()}</div></section>`;}
const accountTypes=[[1,'Conta corrente'],[2,'Poupança'],[3,'Dinheiro / caixa'],[4,'Carteira digital'],[5,'Investimentos'],[99,'Outra']];
function accountsPage(){return `<div class="note" style="margin-bottom:20px">O saldo considera o valor inicial e os lançamentos confirmados de todo o histórico. Arquivar uma conta preserva seus registros e seu saldo.</div><div class="item-grid">${data.accounts.map(a=>`<article class="card item-card ${a.ativa?'':'archived'}"><div class="item-top">${badge('wallet',a.tipoConta===5?'blue':'')}<span class="pill ${a.ativa?'green':''}">${a.ativa?'Ativa':'Arquivada'}</span></div><div><h3>${e(a.nome)}</h3><small>${accountTypes.find(x=>x[0]===a.tipoConta)?.[1]||'Outra'}</small></div><div><div class="eyebrow">SALDO ATUAL</div><div class="big num ${a.saldo<0?'negative':''}">${money(a.saldo)}</div></div><div class="item-bottom"><small>Inicial: ${money(a.saldoInicial)}</small>${canEdit()?`<div class="row-actions">${ib('Editar conta','edit-account','edit',`data-id="${a.id}"`)}${ib(a.ativa?'Arquivar conta':'Reativar conta','toggle-account',a.ativa?'pause':'play',`data-id="${a.id}"`)}</div>`:''}</div></article>`).join('')}</div>${!data.accounts.length?empty('Adicione sua primeira conta','Cadastre uma carteira, caixa ou conta bancária.','new-account','Nova conta','wallet'):''}`;}
function categoriesPage(){return `<div class="categories-grid">${[1,2].map(type=>`<section class="card"><div class="card-head"><div class="inline">${badge(type===1?'up':'down',type===2?'red':'')}<h2>${type===1?'Receitas':'Despesas'}</h2></div><span class="pill">${data.categories.filter(c=>c.tipo===type).length} categorias</span></div><div class="card-body">${data.categories.filter(c=>c.tipo===type).map(c=>`<div class="category-line"><span class="grow">${e(c.nome)}</span>${!c.ativa?'<span class="pill">Arquivada</span>':''}${canEdit()?`<div class="row-actions">${ib('Editar categoria','edit-category','edit',`data-id="${c.id}"`)}${ib(c.ativa?'Arquivar categoria':'Reativar categoria','toggle-category',c.ativa?'pause':'play',`data-id="${c.id}"`)}</div>`:''}</div>`).join('')||empty('Sem categorias','Crie categorias para organizar seus lançamentos.','new-category','Nova categoria','tag',true)}</div></section>`).join('')}</div>`;}
function budgetData(){return data.budgets.filter(b=>`${b.ano}-${String(b.mes).padStart(2,'0')}`===month).map(b=>({...b,name:data.categories.find(c=>c.id===b.categoriaId)?.nome||'Categoria',spent:sum(data.transactions.filter(t=>t.tipo===2&&t.pago&&t.categoriaId===b.categoriaId&&inMonth(t,month)))}));}
function budgetRows(compact=false){const rows=budgetData();if(!rows.length)return empty('Um plano faz a diferença','Defina quanto pretende gastar em cada categoria.','new-budget','Criar orçamento','pie',true);return rows.slice(0,compact?3:rows.length).map(b=>{const pct=b.spent/b.valorLimite*100;return `<div class="budget-row"><div class="inline"><strong>${e(b.name)}</strong><span class="pill ${pct>100?'red':pct>=80?'orange':'green'}">${Math.round(pct)}%</span></div><div class="progress ${pct>100?'over':''}" role="progressbar" aria-label="Orçamento de ${e(b.name)}" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${Math.min(100,Math.round(pct))}" aria-valuetext="${money(b.spent)} de ${money(b.valorLimite)}"><span style="width:${Math.min(100,pct)}%"></span></div><div class="progress-caption"><span>${money(b.spent)} utilizados</span><span>de ${money(b.valorLimite)}</span></div></div>`;}).join('');}
function budgetsPage(){const rows=budgetData();return `<div class="note" style="margin-bottom:20px">Os orçamentos são mensais. O uso considera somente despesas pagas na categoria; contas pendentes continuam no planejamento de caixa.</div>${rows.length?`<div class="item-grid">${rows.map(b=>{const pct=b.spent/b.valorLimite*100;return `<article class="card item-card"><div class="item-top">${badge('pie')}<span class="pill ${pct>100?'red':'green'}">${pct>100?'Limite ultrapassado':'Em acompanhamento'}</span></div><h3>${e(b.name)}</h3><div><div class="big num">${money(b.spent)}</div><small>de ${money(b.valorLimite)} planejados</small><div class="progress ${pct>100?'over':''}"><span style="width:${Math.min(100,pct)}%"></span></div><div class="progress-caption"><span>${Math.round(pct)}% utilizado</span><span>${money(b.valorLimite-b.spent)} restantes</span></div></div>${canEdit()?`<div class="item-bottom">${button('Editar','edit-budget','edit','small',`data-id="${b.id}"`)}${ib('Excluir orçamento','delete-budget','trash',`data-id="${b.id}"`)}</div>`:''}</article>`;}).join('')}</div>`:empty('Planeje seu mês','Cadastre um limite por categoria para acompanhar seus gastos.','new-budget','Criar orçamento','pie')}`;}
function goalsPage(){return `${data.goals.length?`<div class="item-grid">${data.goals.map(g=>`<article class="card item-card"><div class="item-top">${badge('target','blue')}<span class="pill ${g.concluida?'green':g.dataLimite.slice(0,10)<localDate()?'orange':''}">${g.concluida?'Concluída':g.dataLimite.slice(0,10)<localDate()?'Prazo encerrado':'Em andamento'}</span></div><div><h3>${e(g.nome)}</h3><small>${e(g.descricao||'Um passo de cada vez.')}</small></div><div><div class="big num">${money(g.valorAtual)}</div><small>de ${money(g.valorObjetivo)}</small><div class="progress"><span style="width:${g.percentualProgresso}%"></span></div><div class="progress-caption"><span>${g.percentualProgresso}% concluído</span><span>Até ${displayDate(g.dataLimite)}</span></div></div><div class="item-bottom"><small>Reserva informada manualmente</small>${canEdit()?`<div class="row-actions">${ib('Atualizar meta','edit-goal','edit',`data-id="${g.id}"`)}${ib('Excluir meta','delete-goal','trash',`data-id="${g.id}"`)}</div>`:''}</div></article>`).join('')}</div>`:empty('Transforme um objetivo em plano','Defina um valor, um prazo e acompanhe seu progresso.','new-goal','Criar minha primeira meta','target')}<div class="note" style="margin-top:20px">O valor reservado nas metas é um acompanhamento manual. Ele não movimenta nem bloqueia o saldo das contas.</div>`;}
function recurringPage(){return `<div class="note" style="margin-bottom:20px">As recorrências são verificadas a cada minuto enquanto o FinControl está funcionando. Ao reiniciar, os períodos vencidos são recuperados. Os lançamentos são criados como <strong>pendentes</strong>.</div>${canEdit()?`<div style="margin-bottom:20px">${button('Verificar vencimentos agora','generate-recurring','refresh')}</div>`:''}${data.recurring.length?`<div class="item-grid">${data.recurring.map(r=>`<article class="card item-card"><div class="item-top">${badge('repeat',r.tipo===2?'red':'')}<span class="pill ${r.ativa?'green':''}">${r.ativa?'Ativa':'Pausada / encerrada'}</span></div><div><h3>${e(r.descricao)}</h3><small>${e(r.frequencia)} · ${r.tipo===1?'Receita':'Despesa'}</small></div><div class="big num">${money(r.valor)}</div><small>Próximo vencimento: ${displayDate(r.proximaData)}<br>${e(data.accounts.find(a=>a.id===r.contaId)?.nome||'Conta')} · ${e(data.categories.find(c=>c.id===r.categoriaId)?.nome||'Categoria')}</small>${!data.accounts.find(a=>a.id===r.contaId)?.ativa||!data.categories.find(c=>c.id===r.categoriaId)?.ativa?'<div class="notice">Aguardando reativação da conta ou categoria.</div>':''}<div class="item-bottom"><small>${r.fim?'Até '+displayDate(r.fim):'Sem data de término'}</small>${canEdit()?button(r.ativa?'Pausar':'Reativar','toggle-recurring',r.ativa?'pause':'play','small',`data-id="${r.id}"`):''}</div></article>`).join('')}</div>`:empty('Automatize o que se repete','Aluguel, assinaturas, salário ou contratos: configure uma vez e acompanhe.','new-recurring','Criar recorrência','repeat')}`;}
function reportsPage(){const rows=data.transactions.filter(t=>inMonth(t,month)),paid=rows.filter(t=>t.pago),income=sum(paid.filter(t=>t.tipo===1)),expense=sum(paid.filter(t=>t.tipo===2));const pendingIn=sum(rows.filter(t=>!t.pago&&t.tipo===1)),pendingOut=sum(rows.filter(t=>!t.pago&&t.tipo===2));return `<div class="report-totals"><div class="card"><small>Receitas realizadas</small><strong class="num positive">${money(income)}</strong></div><div class="card"><small>Despesas realizadas</small><strong class="num negative">${money(expense)}</strong></div><div class="card"><small>Resultado realizado</small><strong class="num">${money(income-expense)}</strong></div></div><div class="dashboard-grid"><section class="card"><div class="card-head"><h2>Resultado por categoria</h2>${button('Exportar CSV','export-report','download','small')}</div><div class="card-body"><div class="table-wrap"><table class="data-table"><thead><tr><th>Categoria</th><th>Tipo</th><th class="money">Realizado</th></tr></thead><tbody>${data.categories.map(c=>({c,v:sum(paid.filter(t=>t.categoriaId===c.id))})).filter(x=>x.v>0).map(({c,v})=>`<tr><td>${e(c.nome)}</td><td>${c.tipo===1?'Receita':'Despesa'}</td><td class="money num">${money(v)}</td></tr>`).join('')||'<tr><td colspan="3">Sem movimentações confirmadas neste mês.</td></tr>'}</tbody></table></div></div></section><section class="card"><div class="card-head"><h2>Compromissos do período</h2></div><div class="card-body"><div class="list-row">${badge('up')}<div class="grow"><strong>A receber</strong><small>Lançamentos pendentes</small></div><strong class="num positive">${money(pendingIn)}</strong></div><div class="list-row">${badge('down','red')}<div class="grow"><strong>A pagar</strong><small>Lançamentos pendentes</small></div><strong class="num negative">${money(pendingOut)}</strong></div><div class="budget-summary"><small>Resultado previsto do mês</small><h2 class="num" style="margin:6px 0">${money(income-expense+pendingIn-pendingOut)}</h2><p>Realizado + recebimentos pendentes − pagamentos pendentes. Não inclui saldo inicial.</p></div></div></section></div><section class="card report-table"><div class="card-head"><h2>Extrato do período · ${e(monthName(month))}</h2></div>${rows.length?`<div class="table-wrap mobile-cards">${transactionTable(rows,true)}</div>`:empty('Nenhum lançamento neste período','Selecione outro mês para ver o histórico.','','','file',true)}</section>`;}
function importPage(){return `<div class="import-layout"><section class="card"><div class="card-body"><h2>Importar um extrato</h2><p class="section-text">Valores positivos são receitas; negativos, despesas. A importação registra movimentações já realizadas.</p><form id="import-form"><div class="form-error" role="alert"></div><div class="stack"><label class="drop-zone">${badge('upload')}<strong>Escolha seu arquivo CSV ou OFX</strong><small>Até 2 MB · até 5.000 lançamentos</small><input type="file" name="arquivo" accept=".csv,.ofx" required ${!canEdit()?'disabled':''}></label>${select('contaId','Conta de destino',data.accounts.filter(a=>a.ativa).map(a=>[a.id,a.nome]))}${select('categoriaReceitaId','Categoria para receitas',data.categories.filter(c=>c.ativa&&c.tipo===1).map(c=>[c.id,c.nome]))}${select('categoriaDespesaId','Categoria para despesas',data.categories.filter(c=>c.ativa&&c.tipo===2).map(c=>[c.id,c.nome]))}<button class="btn primary" ${!canEdit()?'disabled':''}>${icon('search',16)}Conferir prévia</button></div></form><div style="margin-top:18px">${button('Baixar modelo CSV','csv-model','download','small ghost')}</div><p class="section-text" style="margin-top:10px;margin-bottom:0">CSV: data;descricao;valor;id. Datas em dd/MM/aaaa ou aaaa-MM-dd. A coluna id é opcional e ajuda a identificar duplicatas.</p></div></section><section class="card" id="import-preview"><div class="card-head"><h2>Confira antes de importar</h2></div>${empty('Sua prévia aparecerá aqui','Nenhum lançamento é salvo antes da sua confirmação.','','','file')}</section></div>`;}
function settingsPage(){const pref=store.get('theme')||'system';return `<div class="settings-grid"><section class="card"><div class="card-body"><h2>Seu espaço financeiro</h2><p class="section-text">Mantenha a vida pessoal e os negócios organizados em espaços separados.</p><form id="workspace-form"><div class="form-error" role="alert"></div><div class="stack">${field('nome','Nome do espaço','text',data.workspace.nome,`required maxlength="120" ${isAdmin()?'':'disabled'}`)}${select('perfil','Perfil de uso',[['Pessoal','Finanças pessoais'],['MEI','Microempresa / MEI'],['Empresa','Empresa']],data.workspace.perfil,isAdmin()?'':'disabled')}</div><div class="form-actions">${button('Criar outro espaço','new-workspace','plus')}${isAdmin()?'<button type="submit" class="btn primary">Salvar</button>':''}</div></form></div></section><section class="card"><div class="card-body"><h2>Aparência</h2><p class="section-text">Escolha o que é mais confortável para seus olhos. A preferência é salva neste dispositivo.</p><div class="theme-options">${[['light','Claro','sun'],['dark','Escuro','moon'],['system','Sistema','monitor']].map(([v,t,i])=>button(t,'set-theme',i,pref===v?'selected':'',`data-theme-choice="${v}"`)).join('')}</div><hr style="border:0;border-top:1px solid var(--border);margin:23px 0"><h3>FinControl no seu dispositivo</h3><p class="section-text">Use como aplicativo quando o navegador oferecer a instalação.</p>${button('Instalar aplicativo','install','download')}</div></section><section class="card"><div class="card-body"><h2>Backup e restauração</h2><p class="section-text">Baixe os dados do espaço em JSON. A restauração cria um novo espaço, preservando os dados atuais. O arquivo não contém senhas nem permissões de acesso.</p><div class="file-actions">${isAdmin()?button('Baixar backup','backup','download','primary'):''}${button('Restaurar backup','restore','upload')}</div><input id="restore-file" type="file" accept=".json" hidden><p class="section-text" style="margin-top:15px;margin-bottom:0">Guarde o arquivo em local seguro: ele contém seu histórico financeiro.</p></div></section><section class="card"><div class="card-body"><h2>Segurança da sua conta</h2><p class="section-text">${e(session.user.email)} · A alteração encerra suas sessões nos outros dispositivos.</p><form id="password-form"><div class="form-error" role="alert"></div><div class="stack">${field('senhaAtual','Senha atual','password','','required autocomplete="current-password" maxlength="128"')}${field('novaSenha','Nova senha','password','','required minlength="10" maxlength="128" autocomplete="new-password"')}</div><div class="form-actions"><button class="btn primary" type="submit">Atualizar senha</button></div></form></div></section>${isAdmin()?`<section class="card full"><div class="card-body"><h2>Equipe e permissões</h2><p class="section-text">Adicione alguém já cadastrado neste FinControl. Administradores gerenciam o espaço e backups; editores alteram registros; leitores apenas consultam. Adicionar um e-mail já listado atualiza sua permissão.</p><form id="member-form"><div class="form-error" role="alert"></div><div class="member-form">${field('email','E-mail da pessoa','email','','required maxlength="180"')}${select('papel','Permissão',[['Leitor','Leitor'],['Editor','Editor'],['Administrador','Administrador']],'Leitor')}<button class="btn primary" style="align-self:end">Adicionar</button></div></form><div class="member-list" id="members-list"><div class="loading-state" style="min-height:80px">Carregando equipe…</div></div></div></section>`:''}</div>`;}
async function loadMembers(){const selected=workspaceId;try{const list=await w('/members');if(route!=='settings'||selected!==workspaceId)return;const el=document.querySelector('#members-list');if(el)el.innerHTML=list.map(m=>`<div class="list-row">${badge('users','blue')}<div class="grow"><strong>${e(m.nome)} ${m.acessoId===session.user.id?'(você)':''}</strong><small>${e(m.email)}</small></div><span class="pill">${e(m.papel)}</span>${ib('Remover acesso','remove-member','trash',`data-id="${m.id}"`)}</div>`).join('');}catch(err){const el=document.querySelector('#members-list');if(el)el.textContent=safeError(err);}}
function showModal(title,body,formId='',confirmText='Salvar'){
 returnFocus=document.activeElement;modal.innerHTML=`<div class="modal-header"><h2 id="modal-title">${e(title)}</h2>${ib('Fechar janela','close-modal','close')}</div><div class="modal-body">${formId?`<form id="${formId}"><div class="form-error" role="alert"></div>`:''}${body}${formId?`<div class="form-actions">${button('Cancelar','close-modal')}<button class="btn primary" type="submit">${confirmText}</button></div></form>`:''}</div>`;
 modal.showModal();
}
function closeModal(){modal.close();returnFocus?.focus?.();}
function categoryOptions(type,current){return data.categories.filter(c=>c.tipo===Number(type)&&(c.ativa||c.id===current)).map(c=>[c.id,c.nome+(c.ativa?'':' (arquivada)')]);}
function accountOptions(current){return data.accounts.filter(a=>a.ativa||a.id===current).map(a=>[a.id,a.nome+(a.ativa?'':' (arquivada)')]);}
function transactionModal(id){
 const t=id?data.transactions.find(x=>x.id===id):null;if(id&&!t)throw new Error('Lançamento não encontrado. Atualize a página.');
 if(!data.categories.some(c=>c.ativa)||!data.accounts.some(a=>a.ativa)){showModal('Prepare seu espaço',`<p class="section-text">Cadastre pelo menos uma conta e uma categoria ativas antes de adicionar um lançamento.</p><div class="form-actions">${button('Criar categoria','prepare-category','tag')}${button('Criar conta','prepare-account','wallet','primary')}</div>`);return;}
 const type=t?.tipo||2;
 showModal(t?'Editar lançamento':'Novo lançamento',`<input name="id" type="hidden" value="${t?.id||''}"><div class="form-grid"><div class="full">${field('descricao','Descrição','text',t?.descricao||'','required maxlength="160" placeholder="Ex.: Aluguel, venda ou salário"')}</div>${select('tipo','Tipo',[[2,'Despesa / a pagar'],[1,'Receita / a receber']],type)}${field('valor','Valor (R$)','text',t?moneyInput(t.valor):'','required inputmode="decimal" placeholder="0,00" maxlength="20"')}${field('data','Data / vencimento','date',t?.data.slice(0,10)||localDate(),'required min="1900-01-01" max="9998-12-31"')}${select('contaId','Conta',accountOptions(t?.contaId),t?.contaId,'required')}${select('categoriaId','Categoria',categoryOptions(type,t?.categoriaId),t?.categoriaId,'required')}<label class="check"><input name="pago" type="checkbox" ${t?.pago??true?'checked':''}>Valor já recebido ou pago</label><label class="field full">Observação <span class="muted">(opcional)</span><textarea name="observacao" maxlength="500" placeholder="Cliente, fornecedor, centro de custo ou referência…">${e(t?.observacao||'')}</textarea></label><div class="full note">Para repetir automaticamente, use a seção <strong>Recorrências</strong>.</div></div>`,'transaction-form');
 modal.querySelector('[name=tipo]').addEventListener('change',event=>{modal.querySelector('[name=categoriaId]').innerHTML=categoryOptions(event.target.value,t?.categoriaId).map(([v,n])=>`<option value="${v}">${e(n)}</option>`).join('');});
}
function accountModal(id){const a=data.accounts.find(a=>a.id===id);showModal(a?'Editar conta':'Nova conta',`<input type="hidden" name="id" value="${a?.id||''}"><div class="stack">${field('nome','Nome da conta','text',a?.nome||'','required maxlength="100" placeholder="Ex.: Conta principal"')}${select('tipoConta','Tipo de conta',accountTypes,a?.tipoConta||1)}${field('saldoInicial','Saldo inicial (R$)','text',moneyInput(a?.saldoInicial||0),'required inputmode="decimal" maxlength="20"')}<div class="note">O saldo inicial representa o valor anterior ao seu histórico de lançamentos. ${a?'Alterá-lo recalcula o saldo consolidado.':''}</div></div>`,'account-form');}
function categoryModal(id){const c=data.categories.find(x=>x.id===id);showModal(c?'Editar categoria':'Nova categoria',`<input type="hidden" name="id" value="${c?.id||''}"><div class="stack">${field('nome','Nome da categoria','text',c?.nome||'','required maxlength="100"')}${select('tipo','Tipo',[[2,'Despesa'],[1,'Receita']],c?.tipo||2)}<div class="note">Categorias usadas no histórico não podem mudar de tipo. Arquivar preserva os lançamentos existentes.</div></div>`,'category-form');}
function budgetModal(id){const b=data.budgets.find(x=>x.id===id);if(!data.categories.some(c=>c.ativa&&c.tipo===2)){toast('Crie primeiro uma categoria de despesa.',true);return;}showModal(b?'Editar orçamento':'Novo orçamento',`<input type="hidden" name="id" value="${b?.id||''}"><div class="stack">${select('categoriaId','Categoria de despesa',categoryOptions(2,b?.categoriaId),b?.categoriaId,b?'disabled':'required')}${field('valorLimite','Limite mensal (R$)','text',b?moneyInput(b.valorLimite):'','required inputmode="decimal" maxlength="20"')}${field('mes','Mês do orçamento','month',b?`${b.ano}-${String(b.mes).padStart(2,'0')}`:month,'required min="1901-01" max="9997-12"')}</div>`,'budget-form');}
function goalModal(id){const g=data.goals.find(x=>x.id===id);showModal(g?'Atualizar meta':'Nova meta',`<input type="hidden" name="id" value="${g?.id||''}"><div class="form-grid"><div class="full">${field('nome','Nome da meta','text',g?.nome||'','required maxlength="120" placeholder="Ex.: Reserva de emergência"')}</div>${field('valorObjetivo','Valor objetivo (R$)','text',g?moneyInput(g.valorObjetivo):'','required inputmode="decimal" maxlength="20"')}${field('valorAtual','Valor já reservado (R$)','text',moneyInput(g?.valorAtual||0),'required inputmode="decimal" maxlength="20"')}${field('dataInicio','Data inicial','date',g?.dataInicio.slice(0,10)||localDate(),'required min="1900-01-01" max="9998-12-31"')}${field('dataLimite','Prazo','date',g?.dataLimite.slice(0,10)||'','required min="1900-01-01" max="9998-12-31"')}<label class="field full">Descrição (opcional)<textarea name="descricao" maxlength="500">${e(g?.descricao||'')}</textarea></label></div>`,'goal-form');}
function recurringModal(){if(!data.accounts.some(a=>a.ativa)||!data.categories.some(c=>c.ativa&&c.tipo===2)){toast('Cadastre uma conta e uma categoria de despesa para começar.',true);return;}showModal('Nova recorrência',`<div class="note">Cada vencimento gera um lançamento pendente. Uma recorrência iniciada no passado também gera os períodos já vencidos.</div><div class="form-grid"><div class="full">${field('descricao','Descrição','text','','required maxlength="160" placeholder="Ex.: Aluguel mensal"')}</div>${select('tipo','Tipo',[[2,'Despesa'],[1,'Receita']],2)}${field('valor','Valor por vencimento (R$)','text','','required inputmode="decimal" maxlength="20"')}${select('categoriaId','Categoria',categoryOptions(2),null,'required')}${select('contaId','Conta',accountOptions(),null,'required')}${select('frequencia','Frequência',[['Mensal','Mensal'],['Semanal','Semanal'],['Anual','Anual']],'Mensal')}${field('inicio','Primeiro vencimento','date',localDate(),'required min="2000-01-01" max="2100-12-31"')}${field('fim','Último vencimento (opcional)','date','','min="2000-01-01" max="2100-12-31"')}</div>`,'recurring-form');modal.querySelector('[name=tipo]').addEventListener('change',ev=>{modal.querySelector('[name=categoriaId]').innerHTML=categoryOptions(ev.target.value).map(([v,n])=>`<option value="${v}">${e(n)}</option>`).join('');});}
function workspaceModal(){showModal('Criar outro espaço',`<div class="note">Contas, categorias e lançamentos ficam separados em cada espaço. Você poderá adicionar sua equipe depois.</div><div class="stack">${field('nome','Nome do espaço','text','','required maxlength="120"')}${select('perfil','Perfil de uso',[['Pessoal','Finanças pessoais'],['MEI','Microempresa / MEI'],['Empresa','Empresa']],'Pessoal')}</div>`,'new-workspace-form','Criar espaço');}
function confirmDialog(title,text,onConfirm,label='Confirmar'){showModal(title,`<p style="font-size:13px;line-height:1.8">${e(text)}</p><div class="form-actions">${button('Cancelar','close-modal')}<button class="btn danger" id="confirm-action">${e(label)}</button></div>`);modal.querySelector('#confirm-action').addEventListener('click',async ev=>{ev.currentTarget.disabled=true;try{await onConfirm();closeModal();}catch(err){toast(safeError(err),true);const b=modal.querySelector('#confirm-action');if(b)b.disabled=false;}},{once:false});}
function download(name,content,type='application/json'){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),5000);}
async function refreshSession(id){session=await api('/session');if(id)workspaceId=id;else if(!session.workspaces.some(s=>s.id===workspaceId))workspaceId=session.workspaces[0]?.id;store.set('workspace',workspaceId);renderShell();await reload();}
function closeMenu(){root.querySelector('.shell')?.classList.remove('menu-open');const b=root.querySelector('[data-action=menu]');b?.setAttribute('aria-expanded','false');document.body.style.overflow='';root.querySelector('.main')?.removeAttribute('inert');const side=root.querySelector('.sidebar');if(side&&matchMedia('(max-width:1000px)').matches)side.setAttribute('inert','');}
function openMenu(){const side=root.querySelector('.sidebar');side?.removeAttribute('inert');root.querySelector('.shell')?.classList.add('menu-open');root.querySelector('[data-action=menu]')?.setAttribute('aria-expanded','true');document.body.style.overflow='hidden';root.querySelector('.main')?.setAttribute('inert','');side?.querySelector('select')?.focus();}
async function act(action,el){const id=Number(el?.dataset.id);switch(action){
 case 'retry':return initialize();case 'reload':return reload();case 'theme':return setTheme(document.documentElement.dataset.theme==='dark'?'light':'dark');case 'set-theme':return setTheme(el.dataset.themeChoice);
 case 'auth-login':authTab='login';return renderAuth();case 'auth-register':authTab='register';return renderAuth();case 'close-modal':return closeModal();case 'menu':return openMenu();case 'close-menu':closeMenu();root.querySelector('[data-action=menu]')?.focus();return;
 case 'logout':await api('/auth/logout','POST',{});data=null;session=null;loadId++;return initialize();
 case 'new-transaction':return transactionModal();case 'edit-transaction':return transactionModal(id);
 case 'new-account':return accountModal();case 'edit-account':return accountModal(id);case 'new-category':return categoryModal();case 'edit-category':return categoryModal(id);
 case 'prepare-account':closeModal();return accountModal();case 'prepare-category':closeModal();return categoryModal();
 case 'new-budget':return budgetModal();case 'edit-budget':return budgetModal(id);case 'new-goal':return goalModal();case 'edit-goal':return goalModal(id);case 'new-recurring':return recurringModal();case 'new-workspace':return workspaceModal();
 case 'prev-month':case 'next-month':{const d=new Date(`${month}-15T12:00:00`);d.setMonth(d.getMonth()+(action==='next-month'?1:-1));if(d.getFullYear()<1901||d.getFullYear()>9997)return;month=localDate(d).slice(0,7);store.set('month',month);page=1;return reload();}
 case 'prev-page':case 'next-page':page+=action==='next-page'?1:-1;document.querySelector('#transaction-results').innerHTML=transactionResults();return;
 case 'clear-filters':filters={search:'',type:'',status:'',account:'',category:''};page=1;return renderPage();
 case 'export':download(`fincontrol-${month}.csv`,transactionCsv(currentRows()),'text/csv;charset=utf-8');return;
 case 'export-report':download(`relatorio-${month}.csv`,transactionCsv(data.transactions.filter(t=>inMonth(t,month))),'text/csv;charset=utf-8');return;
 case 'print':window.print();return;
 case 'toggle-paid':{const t=data.transactions.find(x=>x.id===id);await w(`/transactions/${id}/paid`,'PATCH',{pago:!t.pago});await reload();toast(t.pago?'Lançamento marcado como pendente.':'Pagamento / recebimento confirmado.');return;}
 case 'delete-transaction':return confirmDialog('Excluir lançamento?','Esta ação remove o registro e recalcula os saldos. Uma ocorrência automática excluída não será recriada.',async()=>{await w(`/transactions/${id}`,'DELETE');await reload();toast('Lançamento excluído.');},'Excluir');
 case 'toggle-account':case 'toggle-category':{const category=action==='toggle-category',item=(category?data.categories:data.accounts).find(x=>x.id===id),path=category?'categories':'accounts';return confirmDialog(item.ativa?'Arquivar registro?':'Reativar registro?',item.ativa?'O histórico será preservado. O registro deixará de aparecer em novos lançamentos; recorrências vinculadas aguardarão sua reativação.':'O registro voltará a estar disponível para novos lançamentos.',async()=>{await w(`/${path}/${id}`,'PATCH',{ativa:!item.ativa});await reload();toast('Situação atualizada.');});}
 case 'delete-budget':case 'delete-goal':return confirmDialog('Excluir '+(action==='delete-goal'?'meta?':'orçamento?'),'Os lançamentos financeiros serão preservados.',async()=>{await w(`/${action==='delete-goal'?'goals':'budgets'}/${id}`,'DELETE');await reload();toast('Registro excluído.');},'Excluir');
 case 'toggle-recurring':{const r=data.recurring.find(x=>x.id===id);return confirmDialog(r.ativa?'Pausar recorrência?':'Reativar recorrência?',r.ativa?'Novos vencimentos deixarão de ser gerados. Os lançamentos existentes serão preservados.':'A geração será retomada a partir de hoje. Os períodos enquanto esteve pausada serão ignorados.',async()=>{await w(`/recurring/${id}`,'PATCH',{ativa:!r.ativa});await reload();toast('Recorrência atualizada.');});}
 case 'generate-recurring':{const r=await w('/recurring/generate','POST',{});await reload();toast(`${r.gerados} lançamento(s) gerado(s).`);return;}
 case 'backup':{const b=await w('/backup');download(`fincontrol-backup-${localDate()}.json`,JSON.stringify(b,null,2));toast('Backup preparado para download.');return;}
 case 'restore':document.querySelector('#restore-file').click();return;
 case 'remove-member':return confirmDialog('Remover acesso?','A pessoa perderá acesso a este espaço. Os dados financeiros serão mantidos.',async()=>{await w(`/members/${id}`,'DELETE');await refreshSession();toast('Acesso removido.');},'Remover');
 case 'csv-model':download('modelo-extrato.csv','\uFEFFdata;descricao;valor;id\n30/09/2026;Recebimento de cliente;1500,00;exemplo-001\n30/09/2026;Pagamento de fornecedor;-250,50;exemplo-002\n','text/csv;charset=utf-8');return;
 case 'confirm-import':{if(!importPreview||importPreview.workspace!==workspaceId)throw new Error('Confira a prévia novamente.');const r=await w('/import','POST',{...importPreview.request,confirmar:true});importPreview=null;await reload();toast(`${r.novos} lançamento(s) importado(s); ${r.duplicados} duplicata(s) ignorada(s).`);return;}
 case 'install':if(installPrompt){await installPrompt.prompt();installPrompt=null;}else showModal('Usar como aplicativo',`<div class="stack"><p>No Android, procure <strong>Instalar aplicativo</strong> no menu do Chrome. No iPhone ou iPad, use <strong>Compartilhar → Adicionar à Tela de Início</strong> no Safari.</p><p class="note">A instalação depende do navegador e de uma conexão HTTPS (ou localhost no computador). No acesso local por Wi-Fi sem HTTPS, continue usando normalmente pelo navegador. Os dados financeiros precisam de conexão com o computador que executa o sistema.</p>${button('Entendi','close-modal','','primary')}</div>`);return;
 }}
document.addEventListener('click',async ev=>{const el=ev.target.closest('[data-action]');if(!el||el.disabled)return;const action=el.dataset.action;el.disabled=true;try{await act(action,el);}catch(err){toast(safeError(err),true);}finally{if(el.isConnected)el.disabled=false;}});
document.addEventListener('input',ev=>{const name=ev.target.dataset.filter;if(name){filters[name]=ev.target.value;page=1;const result=document.querySelector('#transaction-results');if(result)result.innerHTML=transactionResults();}if(ev.target.closest('#import-form')){importPreview=null;const preview=document.querySelector('#import-preview');if(preview)preview.innerHTML='<div class="card-head"><h2>Confira antes de importar</h2></div>'+empty('Atualize a prévia','Confira novamente após alterar o arquivo ou as opções.','','','file');}});
document.addEventListener('change',async ev=>{try{if(ev.target.id==='workspace'){workspaceId=Number(ev.target.value);data=null;importPreview=null;filters={search:'',type:'',status:'',account:'',category:''};store.set('workspace',workspaceId);await reload();}if(ev.target.id==='month'&&/^\d{4}-\d{2}$/.test(ev.target.value)){month=ev.target.value;store.set('month',month);page=1;await reload();}if(ev.target.id==='restore-file'){const f=ev.target.files[0];ev.target.value='';if(!f)return;if(f.size>7_500_000)throw new Error('O backup deve ter menos de 7,5 MB.');let backup;try{backup=JSON.parse(await f.text());}catch{throw new Error('O arquivo não é um backup JSON válido.');}confirmDialog('Restaurar backup?',`Será criado um novo espaço com os dados de “${String(backup.nome||'Backup')}”. Nenhum espaço atual será substituído.`,async()=>{const r=await api('/restore','POST',backup);data=null;await refreshSession(r.id);toast('Backup restaurado em um novo espaço.');},'Restaurar');}}catch(err){toast(safeError(err),true);}});
document.addEventListener('submit',async ev=>{
 const form=ev.target;if(!(form instanceof HTMLFormElement))return;ev.preventDefault();if(form.dataset.saving)return;form.dataset.saving='true';const errbox=form.querySelector('.form-error');if(errbox)errbox.textContent='';const submit=form.querySelector('[type=submit],button:not([type])');if(submit)submit.disabled=true;
 const f=new FormData(form),v=name=>String(f.get(name)||''),n=name=>Number(v(name)),cash=name=>parseMoney(v(name)),id=n('id');
 try{
 switch(form.getAttribute('id')){
 case 'auth-form':{const payload=authTab==='login'?{email:v('email'),senha:v('senha')}:{nome:v('nome'),email:v('email'),senha:v('senha'),perfil:v('perfil'),espaco:v('espaco'),codigoInicial:v('codigoInicial')};await api('/auth/'+(authTab==='login'?'login':'register'),'POST',payload);data=null;await initialize();return;}
 case 'transaction-form':{const original=data.transactions.find(t=>t.id===id);await w('/transactions'+(id?'/'+id:''),id?'PUT':'POST',{descricao:v('descricao'),valor:cash('valor'),data:v('data'),tipo:n('tipo'),categoriaId:n('categoriaId'),contaId:n('contaId'),observacao:v('observacao')||null,pago:f.has('pago'),recorrente:original?.recorrente||false});break;}
 case 'account-form':await w('/accounts'+(id?'/'+id:''),id?'PUT':'POST',{nome:v('nome'),tipoConta:n('tipoConta'),saldoInicial:cash('saldoInicial')});break;
 case 'category-form':await w('/categories'+(id?'/'+id:''),id?'PUT':'POST',{nome:v('nome'),tipo:n('tipo')});break;
 case 'budget-form':{const [year,mon]=v('mes').split('-').map(Number);await w('/budgets'+(id?'/'+id:''),id?'PUT':'POST',{categoriaId:id?data.budgets.find(b=>b.id===id).categoriaId:n('categoriaId'),valorLimite:cash('valorLimite'),mes:mon,ano:year});break;}
 case 'goal-form':await w('/goals'+(id?'/'+id:''),id?'PUT':'POST',{nome:v('nome'),descricao:v('descricao')||null,valorObjetivo:cash('valorObjetivo'),valorAtual:cash('valorAtual'),dataInicio:v('dataInicio'),dataLimite:v('dataLimite')});break;
 case 'recurring-form':await w('/recurring','POST',{descricao:v('descricao'),valor:cash('valor'),tipo:n('tipo'),categoriaId:n('categoriaId'),contaId:n('contaId'),frequencia:v('frequencia'),inicio:v('inicio'),fim:v('fim')||null});break;
 case 'workspace-form':await w('/settings','PUT',{nome:v('nome'),perfil:v('perfil')});await refreshSession();toast('Espaço atualizado.');return;
 case 'new-workspace-form':{const r=await api('/workspaces','POST',{nome:v('nome'),perfil:v('perfil')});closeModal();data=null;await refreshSession(r.id);toast('Novo espaço criado.');return;}
 case 'password-form':await api('/auth/password','PUT',{senhaAtual:v('senhaAtual'),novaSenha:v('novaSenha')});form.reset();toast('Senha alterada. Outras sessões foram encerradas.');return;
 case 'member-form':await w('/members','POST',{email:v('email'),papel:v('papel')});form.reset();await refreshSession();toast('Permissão de acesso atualizada.');return;
 case 'import-form':{const file=f.get('arquivo');if(!file?.size)throw new Error('Escolha um arquivo.');if(file.size>2_000_000)throw new Error('Envie um arquivo de até 2 MB.');const format=file.name.split('.').pop().toLowerCase();if(!['csv','ofx'].includes(format))throw new Error('Use um arquivo CSV ou OFX.');let content=await file.text();if(content.includes('\uFFFD'))content=new TextDecoder('windows-1252').decode(await file.arrayBuffer());const request={conteudo:content,formato:format,contaId:n('contaId'),categoriaReceitaId:n('categoriaReceitaId'),categoriaDespesaId:n('categoriaDespesaId'),confirmar:false},selected=workspaceId;const result=await w('/import','POST',request);if(selected!==workspaceId)return;importPreview={request,workspace:selected};document.querySelector('#import-preview').innerHTML=`<div class="card-head"><div><h2>Prévia conferida</h2><p>${result.novos} novos · ${result.duplicados} duplicados ignorados · ${result.total} no arquivo</p></div></div><div class="card-body"><div class="note">Confira valores, conta e categorias. A confirmação salva os novos lançamentos como pagos/recebidos. Prévia limitada às primeiras 50 linhas.</div><div class="table-wrap" style="margin-top:15px"><table class="data-table"><thead><tr><th>Data</th><th>Descrição</th><th class="money">Valor</th></tr></thead><tbody>${result.lancamentos.map(r=>`<tr><td>${displayDate(r.data)}</td><td>${e(r.descricao)}</td><td class="money">${money(r.valor)}</td></tr>`).join('')}</tbody></table></div><div class="form-actions">${button('Confirmar importação','confirm-import','check','primary',result.novos?'':'disabled')}</div></div>`;return;}
 default:return;
 }
 closeModal();await reload();toast('Registro salvo com sucesso.');
 }catch(err){if(errbox&&errbox.isConnected){errbox.textContent=safeError(err);errbox.scrollIntoView({block:'nearest'});}else toast(safeError(err),true);}
 finally{delete form.dataset.saving;if(submit?.isConnected)submit.disabled=false;}
});
modal.addEventListener('cancel',()=>{setTimeout(()=>returnFocus?.focus?.(),0);});
document.addEventListener('keydown',ev=>{if(!root.querySelector('.menu-open'))return;if(ev.key==='Escape'){closeMenu();root.querySelector('[data-action=menu]')?.focus();}if(ev.key==='Tab'){const controls=[...root.querySelectorAll('.sidebar a,.sidebar button,.sidebar select')].filter(x=>!x.disabled);if(ev.shiftKey&&document.activeElement===controls[0]){ev.preventDefault();controls.at(-1).focus();}else if(!ev.shiftKey&&document.activeElement===controls.at(-1)){ev.preventDefault();controls[0].focus();}}});
const mobile=matchMedia('(max-width:1000px)');mobile.addEventListener('change',()=>{closeMenu();if(!mobile.matches)root.querySelector('.sidebar')?.removeAttribute('inert');});
function updateOnline(){const b=document.querySelector('#offline-banner');if(b)b.hidden=navigator.onLine;}
window.addEventListener('online',()=>{updateOnline();if(data)reload();});window.addEventListener('offline',updateOnline);
window.addEventListener('beforeinstallprompt',event=>{event.preventDefault();installPrompt=event;});
if('serviceWorker'in navigator&&window.isSecureContext)navigator.serviceWorker.register('/sw.js').catch(()=>{});
await initialize();closeMenu();
